using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class CoordinateWordClampProof {
 class Memory:IHorizontalRasterMemory {public Dictionary<int,byte> Bytes=new Dictionary<int,byte>();public List<string> Events=new List<string>();public void Seed(ushort s,ushort o,ushort v){Bytes[(s<<4)+o]=(byte)v;Bytes[(s<<4)+(ushort)(o+1)]=(byte)(v>>8);}public void Load(ushort s,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++){byte old;int p=(s<<4)+i;if(Bytes.TryGetValue(p,out old)&&old!=b[i])throw new Exception("Alias");Bytes[p]=b[i];}}public ushort ReadWord(ushort s,ushort o){byte a,b;Bytes.TryGetValue((s<<4)+o,out a);Bytes.TryGetValue((s<<4)+(ushort)(o+1),out b);ushort v=(ushort)(a|b<<8);Events.Add("R:"+o+":"+v);return v;}public void WriteWord(ushort s,ushort o,ushort v){Events.Add("W:"+o+":"+v);Seed(s,o,v);}public void OrByte(ushort s,ushort o,byte b){throw new Exception("Video effect");}public Memory Copy(){Memory m=new Memory();foreach(var v in Bytes)m.Bytes[v.Key]=v.Value;return m;}public void Compare(ushort s,byte[] b){if(b.Length!=65536)throw new Exception("Length");for(int i=0;i<65536;i++)if(Bytes[(s<<4)+i]!=b[i])throw new Exception("Segment byte "+i.ToString("X4"));}}
 static uint Interpret(byte[] code,Memory memory,ushort ds,uint flags){int pc=0;bool less=false,equal=false,carry=false;Func<byte> next=()=>code[pc++];Func<ushort> word=()=>{byte b=next();return (ushort)(b|next()<<8);};while(pc<89){switch(next()){
 case 0x83:case 0x81:{byte op=code[pc-1];if(next()!=0x3e)throw new Exception("CMP");ushort at=word(),left=memory.ReadWord(ds,at),right=op==0x83?(ushort)(short)(sbyte)next():word();flags=IndependentFlagArithmetic.Apply(flags,left,right,16,false);less=(short)left<(short)right;equal=left==right;carry=left<right;break;}
 case 0xc7:if(next()!=6)throw new Exception("MOV");ushort dst=word();memory.WriteWord(ds,dst,word());break;
 case 0x7c:case 0x7f:case 0x72:case 0x73:case 0x76:{byte op=code[pc-1];sbyte delta=(sbyte)next();if(op==0x7c?less:op==0x7f?!less&&!equal:op==0x72?carry:op==0x73?!carry:carry||equal)pc+=delta;break;}
 case 0xeb:sbyte jump=(sbyte)next();pc+=jump;break;default:throw new Exception("Opcode");
 }}if(pc!=89)throw new Exception("Exit");return flags;}
 static ushort H(string s){return Convert.ToUInt16(s,16);}
 static int Main(string[] a){try{byte[] raw=File.ReadAllBytes(a[0]),code=new byte[89];Array.Copy(raw,0xc250+0x792,code,0,89);
 if(a.Length>1){string prefix=Path.Combine(a[1],"case-"+a[2]);ushort ds=H(a[3]),ss=H(a[4]);byte[] live=File.ReadAllBytes(prefix+"-code.bin");if(live.Length!=89)throw new Exception("Live length");for(int i=0;i<89;i++)if(live[i]!=code[i])throw new Exception("Live code");Memory m=new Memory();m.Load(ds,File.ReadAllBytes(prefix+"-before-ds.bin"));m.Load(ss,File.ReadAllBytes(prefix+"-before-ss.bin"));uint result=CoordinateWordClamp.Execute(m,ds,Convert.ToUInt32(a[5],16));if(result!=Convert.ToUInt32(a[6],16))throw new Exception("Full flags");m.Compare(ds,File.ReadAllBytes(prefix+"-after-ds.bin"));m.Compare(ss,File.ReadAllBytes(prefix+"-after-ss.bin"));Console.WriteLine("PASS original clamp: 89 live code bytes, full EFLAGS and complete DS/SS views; no GPR changes.");return 0;}
 int count=0;ushort segment=0x2000;for(int n=0;n<65536;n++)for(int k=0;k<8;k++){ushort high=(ushort)(k<2?n:k==2||k==6?0:k==3||k==7?0xffff:k==4?1:0x8000),low=(ushort)(k==0?0:k==1?0xffff:n),secondHigh=(ushort)(k==0||k==2||k==3?0:k==1?0xffff:n),secondLow=(ushort)(k==0||k==4?0:k==5?0xffff:k==3?n^0xffff:n);Memory seed=new Memory();seed.Seed(segment,0xc590,low);seed.Seed(segment,0xc592,high);seed.Seed(segment,0xc594,secondLow);seed.Seed(segment,0xc596,secondHigh);Memory x=seed.Copy(),y=seed.Copy();uint flags=unchecked((uint)(n*65537+0xa55a));uint p=CoordinateWordClamp.Execute(x,segment,flags),q=Interpret(code,y,segment,flags);if(p!=q||x.Events.Count!=y.Events.Count||x.Bytes.Count!=y.Bytes.Count)throw new Exception("Model");for(int i=0;i<x.Events.Count;i++)if(x.Events[i]!=y.Events[i])throw new Exception("Ordered read/write");foreach(var v in x.Bytes)if(y.Bytes[v.Key]!=v.Value)throw new Exception("Memory");count++;}
 Console.WriteLine("PASS "+count+" original-instruction clamp comparisons: all high/low word values under eight layouts, signed high-word/unsigned low-word decisions, inclusive boundaries, ordered reads/writes and full EFLAGS.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
